import{_ as o}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/ON.DXVlsWbj.js";import{_ as e}from"./chunks/EN.P9aPnFBv.js";import{_ as t}from"./chunks/DIS.DdpTdGGD.js";import{_ as s}from"./chunks/OFF.BrU7kQE-.js";import{_ as n,a as i,b as l,c}from"./chunks/M-S-SW-AW-XP24.ELkzeA7z.js";import{_ as p}from"./chunks/M-S-SW-AW-3DM.DGzdotDO.js";import{_ as d,o as u,c as m,a3 as v}from"./chunks/framework.g9mfNVRQ.js";const A=JSON.parse('{"title":"Android Wear","description":"","frontmatter":{"source_hash":"a4207f8d58","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/smartwatch/wear.md","filePath":"fr/smartwatch/wear.md"}'),h={name:"fr/smartwatch/wear.md"};function f(g,r,b,x,q,_){return u(),m("div",null,[...r[0]||(r[0]=[v('<p>Vous trouverez la documentation de référence <a href="https://github.com/NightscoutFoundation/xDrip/blob/master/Documentation/WatchGuide.md" target="_blank" rel="noreferrer">ici</a>.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Options montre intelligente<br>   Intégration Wear OS</p></div><p>Une fois xDrip installé sur la montre appairée à votre téléphone, vous pouvez activer Wear.<br> xDrip communiquera alors avec une version allégée de lui-même sur la montre.</p><div class="admonition xdripitem"><p class="admonition-title">Intégration Wear OS <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Envoyer les données au cadran Wear OS.</p></div><p>Pour quelques combinaisons de capteurs et de montres, xDrip peut être utilisé directement depuis la montre sans que le téléphone soit présent. Voir ci-dessous pour plus d&#39;informations.</p><p>Activer le Service de collecte Wear permet à la montre de prendre le relais du téléphone lorsque xDrip sur le téléphone perd la connexion avec le capteur ou le transmetteur.</p><div class="admonition xdripitem"><p class="admonition-title">Activer le Service de collecte Wear <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Connecter Wear au collecteur BT lorsque le téléphone est hors de portée</p></div><p>Forcer le Service de collecte Wear oblige la montre à être l&#39;appareil principal connecté au capteur ou au transmetteur, même si le téléphone est à proximité (recommandé).</p><div class="admonition xdripitem"><p class="admonition-title">Forcer le Service de collecte Wear <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Forcer le téléphone à utiliser le Service de collecte Wear</p></div><p>Désactiver le forçage en cas de batterie faible fait que la montre abandonne la connexion au capteur ou au transmetteur pour la rendre au téléphone lorsque sa batterie est trop faible.</p><div class="admonition xdripitem"><p class="admonition-title">Désactiver le forçage en cas de batterie faible <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p>Désactiver le forçage du Service de Collection Wear en cas de batterie faible</p></div><p>Désactiver le forçage en cas de lectures manquées fait que la montre abandonne la connexion au capteur ou au transmetteur pour la rendre au téléphone après une certaine durée sans valeurs, définie dans le menu ci-dessous.</p><div class="admonition xdripitem"><p class="admonition-title">Désactiver le forçage vers Wear en cas de lectures manquées <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p>Désactiver le forçage du Service de Collecte Wear si des Minutes sont passées depuis la dernière lecture</p></div><p>Utiliser uniquement Wear peut être activé si vous avez configuré la montre une fois mais n&#39;utiliserez pas votre téléphone pour vous connecter au capteur ou au transmetteur.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser uniquement Wear <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p>Si vous prévoyez d&#39;utiliser seulement un collecteur Wear et jamais votre téléphone.</p></div><p>Si vous avez plusieurs montres Android Wear avec xDrip, vous pouvez choisir laquelle sera le collecteur. Les autres afficheront seulement les données de xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Périphérique qui exécute le Service de Collecte</p></div><div class="info custom-block"><p class="custom-block-title">Changer de montre</p><p>Lorsque vous passez d&#39;une montre à l&#39;autre, xDrip peut ne pas réussir à communiquer son intention aux deux montres si l&#39;une d&#39;elles est éteinte. Si vous voulez changer de montre collectrice, forcez le collecteur dans xDrip et forcez aussi le collecteur dans le menu xDrip Prefs de la montre.</p></div><p>Synchroniser les logs Wear est une fonction très utile en cas de problème : elle ajoute les journaux de la montre au <a href="./../use/3dotsmenu.html#events-log">journal des événements</a> de xDrip, avec un préfixe qui indique que l&#39;activité a lieu sur la montre. Par défaut, le préfixe est <code>wear</code>, mais vous pouvez le personnaliser. Il est recommandé de garder cette option activée.</p><div class="admonition xdripitem"><p class="admonition-title">Synchroniser les logs Wear <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Envoyer les logs Wear vers l’observateur d’événements</p></div><p>Afficher les Traitements ajoute les symboles des traitements sur le graphique de la montre.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher les Traitements <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Afficher les points de Traitements sur le graphique</p></div><h2 id="standalone-collector-mode" tabindex="-1">Mode collecteur autonome <a class="header-anchor" href="#standalone-collector-mode" aria-label="Permalink to &quot;Mode collecteur autonome {#standalone-collector-mode}&quot;">​</a></h2><p>L&#39;extension Wear de xDrip contient aussi la partie de xDrip qui se connecte à certains capteurs : la montre peut donc remplacer le téléphone et prendre en charge la communication et les valeurs, sans que votre téléphone soit à proximité.</p><p>Cette fonction n&#39;est pas disponible pour tous les capteurs, voir le tableau ci-dessous :</p><table tabindex="0"><thead><tr><th>Capteur</th><th>Wear 1.x</th><th>Wear 2.x</th><th>Wear 3+</th></tr></thead><tbody><tr><td>G5/G6/1</td><td>Oui</td><td>Limité*</td><td>Non</td></tr><tr><td>G7/1+</td><td>Non</td><td>Non</td><td>Non</td></tr><tr><td>Libre 1 avec transmetteur</td><td>Oui</td><td>Oui</td><td></td></tr><tr><td>Libre 14 jours US avec transmetteur</td><td>Oui**</td><td>Oui**</td><td></td></tr><tr><td>Libre 2/2+ EU sans transmetteur</td><td>Non</td><td>Non</td><td></td></tr><tr><td>Libre 2/2+ EU avec transmetteur</td><td>Oui**</td><td>Oui**</td><td></td></tr></tbody></table><p><em><strong>Limité*:</strong></em> la plupart des montres Android Wear présentent des bugs qui les empêchent de fonctionner correctement avec le G5/G6. Dans le meilleur des cas, vous aurez une valeur toutes les 10 minutes. Certaines montres peuvent être <a href="https://github.com/NightscoutFoundation/xDrip/wiki/Patching-Android-Wear-devices-for-use-with-the-G5" target="_blank" rel="noreferrer">modifiées</a> pour obtenir une valeur toutes les 5 minutes.</p><div class="info custom-block"><p class="custom-block-title">Pourquoi ma montre ne peut-elle pas collecter seule les données d&#39;un G5/G6 ?</p><p>La plupart des montres Android Wear sont livrées avec un firmware Bluetooth bogué qui casse le cycle de connexion du G5/G6 : la montre manque des valeurs ou n&#39;en reçoit qu&#39;une toutes les 10 minutes. La seule solution trouvée a été de modifier le firmware de la montre elle-même : déverrouiller le bootloader et flasher un correctif via un recovery personnalisé. Cela annule la garantie et n&#39;existe que pour quelques montres anciennes (Asus Zenwatch 2/3, Huawei Watch et Watch 2, LG G Watch, Polar M600). L&#39;explication complète, la liste des montres prises en charge et les téléchargements « care pack » se trouvent sur la page wiki <a href="https://github.com/NightscoutFoundation/xDrip/wiki/Patching-Android-Wear-devices-for-use-with-the-G5" target="_blank" rel="noreferrer">Patching Android Wear devices for use with the G5</a>. Si votre montre n&#39;y figure pas, elle ne peut pas collecter nativement les données d&#39;un G5/G6 : utilisez-la plutôt comme affichage du téléphone.</p></div><p><em><strong>Oui**:</strong></em> il vous faut un téléphone fonctionnant avec <a href="./../use/OOP.html">OOP1</a> ou <a href="./../use/OOP.html#oop2">OOP2</a>, et cette même application OOP doit aussi être <a href="./../troubleshoot/ADB.html#smartwatch">chargée</a> sur votre montre. Certains transmetteurs peuvent ne pas être compatibles.</p><h3 id="prerequisites" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prérequis {#prerequisites}&quot;">​</a></h3><p>La fonction est disponible pour les combinaisons capteur/montre décrites ci-dessus.</p><p>L&#39;extension xDrip est installée sur la montre, dans la même version que celle de votre téléphone.</p><p>La connectivité de xDrip est bonne sur votre téléphone (c&#39;est-à-dire que les paramètres Bluetooth sont correctement définis).</p><p>xDrip sur la montre doit être autorisé à accéder à la position.<br><img src="'+n+'" style="zoom:75%;"></p><h3 id="recommended-sequence" tabindex="-1">Séquence recommandée <a class="header-anchor" href="#recommended-sequence" aria-label="Permalink to &quot;Séquence recommandée {#recommended-sequence}&quot;">​</a></h3><p>Première tentative ou reprise après un échec :</p><p>1 - Dans xDrip sur votre téléphone : désactivez le forçage du collecteur, puis la collecte, puis Wear, dans cet ordre.</p><div class="admonition xdripitem"><p class="admonition-title">Forcer le Service de collecte Wear <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Activer le Service de collecte Wear <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Intégration Wear OS <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p></div><p>2 - Activez les journaux Wear.</p><div class="admonition xdripitem"><p class="admonition-title">Synchroniser les logs Wear <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Envoyer les logs Wear vers l’observateur d’événements</p></div><p>3 - Redémarrez votre montre. Attendez qu&#39;elle ait complètement démarré.</p><p>4 - Sur votre téléphone, activez uniquement Wear.</p><div class="admonition xdripitem"><p class="admonition-title">Intégration Wear OS <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>5 - Attendez que le graphique xDrip soit entièrement affiché sur la montre (attendre une nouvelle mesure ne fait pas de mal).</p><p>6 - Gardez le téléphone, la montre et le capteur proches les uns des autres, et activez d&#39;abord la collecte, puis le forçage du collecteur.</p><div class="admonition xdripitem"><p class="admonition-title">Activer le Service de collecte Wear <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Forcer le Service de collecte Wear <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>7 - L&#39;appairage prend généralement 10 minutes : ouvrez le journal des événements de xDrip sur le téléphone et attendez les événements commençant par <code>wear</code>.<br><img src="'+i+'" style="zoom:75%;"></p><p>8 - Si tout s&#39;est bien passé, la montre devrait maintenant être en mode autonome.</p><h5 id="if-the-watch-doesnt-connect-to-the-bridge" tabindex="-1">Si la montre ne se connecte pas au transmetteur : <a class="header-anchor" href="#if-the-watch-doesnt-connect-to-the-bridge" aria-label="Permalink to &quot;Si la montre ne se connecte pas au transmetteur : {#if-the-watch-doesnt-connect-to-the-bridge}&quot;">​</a></h5><ul><li>Dans le menu xDrip Prefs de la montre, cochez Force Collector.<br><img src="'+l+'" style="zoom:75%;"></li><li>Depuis le menu à trois points du cadran xDrip, choisissez Restart Collector.<br><img src="'+p+'" style="zoom:75%;"></li><li>Dans les paramètres Bluetooth de la montre, trouvez votre transmetteur et faites semblant de l&#39;appairer (vous ne pouvez pas appairer un Miaomiao avec la montre, mais elle va essayer d&#39;établir une liaison avec lui). Une fois l&#39;appairage échoué, attendez 10 minutes que les valeurs apparaissent.</li><li>Si les valeurs n&#39;apparaissent pas, désactivez Force Collector et recommencez la séquence.</li></ul><h2 id="sharing-data-in-standalone-mode" tabindex="-1">Partager les données en mode autonome <a class="header-anchor" href="#sharing-data-in-standalone-mode" aria-label="Permalink to &quot;Partager les données en mode autonome {#sharing-data-in-standalone-mode}&quot;">​</a></h2><p>Si vous voulez que la montre partage les données (xDrip Sync, Nightscout…), elle doit être connectée à votre téléphone et votre téléphone doit être connecté à Internet.</p><p>Ils n&#39;ont pas besoin d&#39;être au même endroit, mais la montre elle-même ne partage pas les données directement : elle les envoie à votre téléphone, et c&#39;est votre téléphone qui les partage. Si la montre est connectée à Internet par Wi-Fi ou par une carte SIM avec forfait de données, elle devra les envoyer à votre téléphone (lui aussi connecté à Internet) et c&#39;est votre téléphone qui partagera les données. Tant qu&#39;ils sont tous les deux connectés à Internet, ils n&#39;ont pas besoin d&#39;être proches l&#39;un de l&#39;autre.</p><img src="'+c+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',59)])])}const k=d(h,[["render",f]]);export{A as __pageData,k as default};
